csui.define('csui/controls/checkbox/checkbox.view',['csui/lib/jquery',
  'csui/lib/underscore',
  'csui/lib/backbone',
  'csui/lib/marionette',
  'i18n!csui/controls/checkbox/impl/nls/lang',
  'hbs!csui/controls/checkbox/impl/checkbox.view',
  'css!csui/controls/control/impl/control',
  'css!csui/controls/checkbox/impl/checkbox.view'
], function ($, _, Backbone, Marionette, lang, template) {
  'use strict';

  /**
   * @class Checkbox
   * @fires click - on the view model
   * @description

   ## Checkbox Control

   The checkbox.view.js implements a marionette.js view that renders a checkbox through the checkbox web-component.

   The checkbox.view creates a model in its constructor to store view state.

   The attribute which stores the checked state is *checked* and can have these states:
   * 'true'
   * 'false'
   * 'mixed'
   */
  return Marionette.ItemView.extend(/** @lends Checkbox# */ {

    // all controls should have csui-control-view for applying common css */
    className: 'csui-control-view csui-checkbox-view',
    template: template,

    /**
     * @returns as needed for the otc-checkbox template
     */
    templateHelpers: function () {
      const disabledState = this.model.get('disabled') ? 'disabled' : '';
      const checkedState = this.model.get('checked') === 'true' ? 'checked' : '';
      const indeterminate = this.model.get('checked') === 'mixed' ? 'indeterminate' : '';
      const isInteractiveOnly = !this.label;
      const interactiveOnly = isInteractiveOnly ? 'interactiveonly' : '';
      const titleValue = this.title ? this.title : '';
      const labelValue = isInteractiveOnly ? '' : this.label;
      const arialabelValue = this.ariaLabel;
      const infoMessage = this.infoMessage ? this.infoMessage : '';

      return {
        disabled: disabledState,
        checked: checkedState,
        indeterminate: indeterminate,
        interactiveOnly: interactiveOnly,
        title: titleValue,
        ariaLabel: arialabelValue,
        label: labelValue,
        infoMessage: infoMessage
      };
    },

    ui: {
      cb: 'otc-checkbox.csui-control.csui-checkbox'
    },

    /**
     * @name Checkbox
     * @extends Marionette.ItemView
     * @constructs
     * @param options {Object} - Recognized option properties:
     * @param options.disabled {Boolean} - Initial *disabled* state. Default is *false*.
     * @param options.checked {String} -  Initial *checked* state. Default is *'false'*.
     * @param options.label {String} - Visible label of the checkbox. When absent then no visual space will be reserved and the ariaLabel needs to provide the a11y text.
     * @param options.ariaLabel {String} - Provides the accessible name if no visible label was set. A visible label wins!
     * @param options.infoMessage {String} - Shows the informational text below the control. Also works without any visible text for the screenreader user.
     * @param options.title {String} - *title* attribute, set on the HTML markup of the control. Default is ''.
     * @param options.model {Object} - Model to use as view model.
     */
    constructor: function Checkbox(options) {
      options || (options = {});

      this.label = options.label;
      this.ariaLabel = options.ariaLabel;
      this.title = options.title;
      this.infoMessage = options.infoMessage;
      if (!options.model) {
        options.model = new Backbone.Model(
            {disabled: options.disabled === undefined ? false : options.disabled}
        );
      }
      Marionette.ItemView.prototype.constructor.call(this, options);
      this._setChecked(options.checked, {silent: true});

      this._undelegateModelAndCollectionEvents();

      // setup specific model events but don't call render, but instead change specific attributes
      this.listenTo(this.model, 'change:disabled', this._handleDisableChanged);
      this.listenTo(this.model, 'change:checked', this._handleCheckedChanged);
    },

    onRender: function() {
      this.ui.cb[0].addEventListener('change', () => this._toggleChecked());
    },

    /**
     * programmatically set the checked state, eg. when state is controlled by other UI elements
     * @param state
     */
    setChecked: function (state) {
      var options = {silent: false};
      if (this.model.get('disabled')) {
        options.silent = true;
      }
      this._setChecked(state, options);
    },

    /**
     * set disabled state
     * @param state
     */
    setDisabled: function (state) {
      this.model.set('disabled', !!state);
    },

    /**
     * push change to disabled down to the otc-checkbox
     * @private
     */
    _handleDisableChanged: function () {
      var disabled = this.model.get('disabled');
      this.ui.cb.prop('disabled', disabled);
    },

    /**
     * after a model state push the model-state down to the otc-checkbox
     * @private
     */
     _handleCheckedChanged: function () {
      var modelChecked = this.model.get("checked");

      const cbType = this.model.get("schema")?.type;
      if (cbType === 'checkboxV2') {
        let data = {
          fieldvalue: modelChecked === 'true',
          fieldid: this.options.dataId,
          fieldpath: this.options.path,
          targetfieldpath: this.options.path,
          fieldView: this
        };
        // this is to set the alpacafield value to its state i.e., true or false, getValue from formView.getValues() is returning false even if it is true.
        this.options.alpacaField.setValue(data.fieldvalue);
        const event = $.Event('field:changed');
        _.extend(event, data);
        this.$el.trigger(event);
      }

      this.ui.cb.prop('checked', modelChecked === 'true');
      if (modelChecked === 'mixed') {
        this.ui.cb.attr('indeterminate', '');
      } else {
        this.ui.cb.removeAttr('indeterminate');
      }
    },

    _setChecked: function (state, options) {
      switch (state) {
      case 'true':
      case true:
        this.model.set('checked','true', options);
        break;
      case 'mixed':
        this.model.set('checked', 'mixed', options);
        break;
      default:
        this.model.set('checked', 'false', options);
        break;
      }
    },

    /**
     * triggered through change events from the underlying otc-checkbox
     * @private
     */
    _toggleChecked: function () {
      if (this.model.get('disabled')) {
        // don't change checkbox and don't fire events, because it's disabled
        return;
      }

      // first trigger a clicked event
      var modelChecked = this.model.get('checked');
      var args = {sender: this, model: this.model};
      this.triggerMethod('clicked', args);

      // if no listener set cancel=true on the event args then toggle the checked state
      if (!args.cancel) {
        if (!modelChecked || modelChecked === 'false' || modelChecked === 'mixed') {
          this.model.set('checked', 'true');
        } else {
          this.model.set('checked', 'false');
        }
      }
    }

  });
});